export function distanceKm(a,b){const rad=Math.PI/180,dLat=(b[1]-a[1])*rad,dLon=(b[0]-a[0])*rad;const h=Math.sin(dLat/2)**2+Math.cos(a[1]*rad)*Math.cos(b[1]*rad)*Math.sin(dLon/2)**2;return 6371*2*Math.atan2(Math.sqrt(h),Math.sqrt(1-h));}
export function nearestStations(coord,stations,limit=3){if(!Array.isArray(coord)||coord.length!==2||!coord.every(Number.isFinite)||coord[0]<103.59||coord[0]>104.12||coord[1]<1.20||coord[1]>1.48)throw new Error('This planner covers Singapore. Search for a station if you are outside Singapore.');return Object.values(stations).filter(s=>s.coord?.length===2).map(s=>({...s,distance:distanceKm(coord,s.coord)})).sort((a,b)=>a.distance-b.distance).slice(0,limit);}
export function validatePosition(position,stations,now=Date.now()){const {longitude,latitude,accuracy}=position.coords||{};if(!Number.isFinite(accuracy)||accuracy>1000)throw new Error('Your location is too approximate. Try again outdoors, or choose a station manually.');if(!Number.isFinite(position.timestamp)||now-position.timestamp>120000)throw new Error('That location is out of date. Please try again.');const coord=[longitude,latitude],nearby=nearestStations(coord,stations);if(!nearby.length||nearby[0].distance>3)throw new Error('No station is within 3 km. Choose a station manually; a bus or taxi connection may be needed.');return {coord,accuracy,nearby,timestamp:position.timestamp};}
export function gpsError(error){return ({1:'Location permission was denied. Allow location access in your browser settings, or search for a station.',2:'Your location could not be found. Try again outdoors, or search for a station.',3:'Finding your location took too long. Try again, or search for a station.'})[error.code]||error.message||'Location is unavailable. Search for a station instead.';}
